+  api project(':libs:elasticsearch-grok')
+  api "com.ibm.icu:icu4j:${versions.icu4j}"
+  api "net.sf.supercsv:super-csv:${versions.supercsv}"
+}
+
+addQaCheckDependencies()
+
+tasks.named("testingConventions").configure { enabled = false }
